window.BlogStudio=(()=>{
  const {client,escape:esc,safeURL}=PortfolioCMS;
  let ctx,drafts=[],owner='',editor=null,view='published';
  const prefix=()=>`sathwik-blog-draft:${owner}:`;
  async function query(q){const r=await q;if(r.error)throw r.error;return r.data}
  function localDrafts(){const found=[];try{for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key.startsWith(prefix())){try{const d=JSON.parse(localStorage.getItem(key));if(d?.id&&d?.content)found.push(d)}catch{}}}}catch{}return found}
  async function load(){const {data:{session}}=await client.auth.getSession();owner=session?.user?.id||'';drafts=await query(client.from('portfolio_post_drafts').select('*').order('updated_at',{ascending:false}));}
  function combined(){const result=new Map(drafts.filter(d=>!d.archived).map(d=>[d.id,d]));for(const local of localDrafts()){const cloud=drafts.find(d=>d.id===local.id);if(!cloud||Date.parse(local.updated_at)>Date.parse(cloud.updated_at)){result.set(local.id,{...local,local:true})}}return [...result.values()].sort((a,b)=>Date.parse(b.updated_at)-Date.parse(a.updated_at))}
  function configure(context){ctx=context}
  function date(value){return new Date(value).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}
  function remember(id){try{sessionStorage.setItem('sathwik-open-blog',id)}catch{}}
  function clearRemember(){try{sessionStorage.removeItem('sathwik-open-blog')}catch{}}
  function resume(){let id;try{id=sessionStorage.getItem('sathwik-open-blog')}catch{}if(!id)return false;const draft=combined().find(d=>d.id===id),post=ctx.posts().find(p=>p.id===id);if(draft||post){open(post,draft);return true}return false}
  function render(next=view){if(editor){clearTimeout(editor.timer);editor.resizeController?.abort();editor.closed=true;}editor=null;view=next;clearRemember();const all=combined(),posts=ctx.posts();const legacy=posts.filter(p=>!p.published&&!p.archived&&!all.some(d=>d.id===p.id));const items=view==='drafts'?[...all.map(d=>({...d.content,id:d.id,draft:d})),...legacy]:posts.filter(p=>view==='archived'?p.archived:p.published&&!p.archived);
    ctx.root.innerHTML=ctx.heading(view==='drafts'?'Thoughts in progress.':view==='archived'?'Kept for another day.':'Your published stories.',view==='drafts'?'Private drafts save as you write. Pick up exactly where you left off.':'Read, refine, and publish in the same typography as your portfolio.','<button id="new-blog" class="admin-button">Write a post +</button>')+`<div class="admin-tabs blog-tabs"><button data-blog-view="published" class="${view==='published'?'active':''}">Published <small>${posts.filter(p=>p.published&&!p.archived).length}</small></button><button data-blog-view="drafts" class="${view==='drafts'?'active':''}">Drafts <small>${all.length+legacy.length}</small></button><button data-blog-view="archived" class="${view==='archived'?'active':''}">Archived</button></div><div class="blog-library">${items.length?items.map(p=>`<article class="blog-library-card">${safeURL(p.cover_url)?`<img src="${esc(safeURL(p.cover_url))}" alt="${esc(p.title||'Post cover')}" loading="lazy">`:'<div class="blog-library-art" aria-hidden="true">✳</div>'}<div><span class="eyebrow">${p.draft?'PRIVATE DRAFT'+(posts.some(s=>s.id===p.id&&s.published)?' · REVISION':''):p.archived?'ARCHIVED':p.published?'PUBLISHED':'DRAFT'}</span><h2>${esc(p.title||'Untitled thought')}</h2><p>${esc(p.excerpt||BlogContent.text(p.body_html||'').slice(0,160)||'Your next idea starts here.')}</p>${p.draft?`<small>${p.draft.local?'Saved on this device':'Draft saved'} · ${esc(date(p.draft.updated_at))}</small>`:''}<div class="blog-library-actions"><button class="secondary-button" data-open-blog="${esc(p.id)}">${view==='drafts'?'Continue writing':'Read & edit'} ↗</button>${p.published&&!p.archived?`<a href="/blogs/?post=${encodeURIComponent(p.slug)}" target="_blank" rel="noopener">View on website ↗</a>`:''}${!p.draft?`<button class="text-link" data-blog-archive="${esc(p.id)}">${p.archived?'Restore':'Archive'}</button>`:''}</div></div></article>`).join(''):`<div class="blog-library-empty"><span>✳</span><h2>${view==='drafts'?'A little room to think.':'The next story is yours.'}</h2><p>${view==='drafts'?'Start writing. Your work will appear here automatically.':'Write a post and publish when it feels ready.'}</p></div>`}</div>`;
    ctx.root.querySelector('#new-blog').onclick=()=>open();ctx.root.querySelectorAll('[data-blog-view]').forEach(b=>b.onclick=()=>ctx.navigate(b.dataset.blogView));ctx.root.querySelectorAll('[data-open-blog]').forEach(b=>b.onclick=()=>{const p=posts.find(p=>p.id===b.dataset.openBlog),d=all.find(d=>d.id===b.dataset.openBlog);open(p,d)});ctx.root.querySelectorAll('[data-blog-archive]').forEach(b=>b.onclick=()=>ctx.archive(posts.find(p=>p.id===b.dataset.blogArchive)));
  }
  const tool=(command,label,text)=>`<button type="button" data-command="${command}" aria-label="${label}" title="${label}">${text}</button>`;
  function open(post,draft){if(!draft&&post)draft=combined().find(d=>d.id===post.id);const data={id:post?.id||draft?.id||crypto.randomUUID(),title:'',slug:'',cover_url:'',body:'',body_html:'',...post,...draft?.content};const cloud=drafts.find(d=>d.id===data.id);editor={id:data.id,post,stamp:cloud?.updated_at||null,cloudExists:!!cloud,revision:0,saved:-1,queue:Promise.resolve(),timer:null,range:null,closed:false,localFailed:false};const e=editor;ctx.setEditor(e);remember(e.id);
    ctx.root.innerHTML=`<div class="writer-heading"><div><span class="eyebrow">THE WRITING ROOM / ${post?.published?'DRAFT REVISION':'PRIVATE DRAFT'}</span><h1>Give the thought some space.</h1></div><button type="button" id="writer-back" class="text-link">← Back to drafts</button></div><div class="writer-bar"><span id="draft-status" role="status" aria-live="polite">${draft?'Draft restored.':'Start writing · drafts save automatically.'}</span><div><button type="button" id="writer-save" class="secondary-button">Save draft</button><button type="button" id="writer-preview" class="secondary-button">Read preview</button><button type="button" id="writer-publish" class="admin-button">${post?.published?'Publish changes':'Publish post'} ↗</button></div></div><section class="writing-room"><div class="writer-toolbar" role="toolbar" aria-label="Text formatting"><label class="sr-only" for="writer-block">Paragraph style</label><select id="writer-block" aria-label="Paragraph style"><option value="p">Paragraph</option><option value="h2">Heading 1</option><option value="h3">Heading 2</option><option value="h4">Heading 3</option><option value="blockquote">Quote</option><option value="pre">Code</option></select><select id="writer-size" aria-label="Text size"><option value="3">Normal size</option><option value="2">Small</option><option value="4">Large</option><option value="5">Extra large</option><option value="6">Display</option></select><span class="toolbar-separator"></span>${tool('bold','Bold','<b>B</b>')}${tool('italic','Italic','<i>I</i>')}${tool('underline','Underline','<u>U</u>')}${tool('strikeThrough','Strikethrough','<s>S</s>')}<label class="color-tool" title="Text color"><span>A</span><input id="writer-color" type="color" value="#30372a" aria-label="Text color"></label><label class="color-tool highlight-tool" title="Highlight color"><span>▰</span><input id="writer-highlight" type="color" value="#e2d8ef" aria-label="Highlight color"></label><span class="toolbar-separator"></span>${tool('insertUnorderedList','Bullet list','• List')}${tool('insertOrderedList','Numbered list','1. List')}${tool('justifyLeft','Align left','≡')}${tool('justifyCenter','Align center','☰')}${tool('justifyRight','Align right','≡')}${tool('link','Insert link','↗ Link')}${tool('image','Add inline image','▧ Image')}${tool('insertHorizontalRule','Divider','—')}${tool('removeFormat','Clear formatting','Tx')}${tool('undo','Undo','↶')}${tool('redo','Redo','↷')}</div><div class="writer-paper"><textarea id="writer-title" aria-label="Post title" placeholder="An idea worth sharing…" maxlength="200" rows="1">${esc(data.title)}</textarea><p class="writer-byline">By Sathwik Tadivaka · <span id="writer-count">0 words</span></p><div id="writer-canvas" class="rich-content" contenteditable="true" role="textbox" aria-label="Blog writing canvas" aria-multiline="true" data-placeholder="Start with a thought. Add words, images, and a little curiosity.">${BlogContent.render(data)}</div><article id="writer-reader" hidden class="rich-content" aria-label="Blog reading preview"></article></div></section><details class="writer-options"><summary>Post settings · URL & cover image</summary><div class="field-pair"><label>URL slug<input id="writer-slug" value="${esc(data.slug)}" maxlength="200" placeholder="generated-from-your-title"></label><label>Cover image URL<input id="writer-cover" value="${esc(data.cover_url)}" placeholder="https://… or /assets/…"></label></div><label>Upload cover image<input id="writer-cover-upload" type="file" accept="image/jpeg,image/png,image/webp,image/avif"></label><p class="hint">The first lines of your canvas become the card introduction. Body fonts always match the website. ${ctx.enabled()?'Publishing makes this post visible on /blogs.':'The blog is disabled; enable it in Site settings to show published posts.'}</p>${post?.published?'<button type="button" id="writer-unpublish" class="secondary-button">Move published post to drafts</button>':''}</details><input type="file" id="writer-image-upload" accept="image/jpeg,image/png,image/webp,image/avif" hidden><dialog id="writer-insert"><h2 id="writer-insert-title">Add a link</h2><form id="writer-insert-form"><label>HTTPS URL<input id="writer-insert-url" type="url" required placeholder="https://…"></label><label id="writer-alt-wrap" hidden>Image description<input id="writer-insert-alt" maxlength="300"></label><div id="writer-image-options" hidden><label>Image width<select id="writer-image-width"><option value="100">Full canvas</option><option value="65">Medium · 65%</option><option value="40">Small · 40%</option></select></label><label>Upload an image<input id="writer-inline-file" type="file" accept="image/jpeg,image/png,image/webp,image/avif"></label><p class="hint">Choose a file or paste its HTTPS URL. JPG, PNG, WebP or AVIF, up to 10 MB.</p></div><div class="form-actions"><button type="submit" class="admin-button">Insert</button><button type="button" id="writer-insert-cancel" class="secondary-button">Cancel</button></div></form></dialog>`;
    const root=ctx.root,canvas=root.querySelector('#writer-canvas'),status=root.querySelector('#draft-status'),title=root.querySelector('#writer-title'),slug=root.querySelector('#writer-slug');
    const get=()=>{const html=BlogContent.sanitize(canvas.innerHTML),body=BlogContent.text(html);return {id:e.id,title:title.value.trim(),slug:slug.value.trim(),body_html:html,body,excerpt:body.replace(/\s+/g,' ').slice(0,240),cover_url:root.querySelector('#writer-cover').value.trim()}};
    const setStatus=(text,error=false)=>{if(editor!==e||e.closed)return;status.textContent=text;status.classList.toggle('save-error',error)};
    function local(){if(e.closed)return;const value={id:e.id,content:get(),updated_at:new Date().toISOString()};try{localStorage.setItem(prefix()+e.id,JSON.stringify(value));e.localFailed=false}catch{e.localFailed=true;setStatus('Device backup unavailable. Keep this tab open until cloud save completes.',true)}return value}
    function change(){if(e.closed)return;e.revision++;e.dirty=true;local();count();setStatus(e.localFailed?'Waiting for cloud save…':'Saved on this device · syncing draft…');clearTimeout(e.timer);e.timer=setTimeout(()=>save().catch(()=>{}),900)}
    function count(){const words=BlogContent.text(canvas.innerHTML).split(/\s+/).filter(Boolean).length;root.querySelector('#writer-count').textContent=`${words} ${words===1?'word':'words'} · ${Math.max(1,Math.ceil(words/200))} min read`}
    function save(){clearTimeout(e.timer);e.queue=e.queue.catch(()=>{}).then(async()=>{if(e.closed)return;const snapshot=get(),revision=e.revision;if(!snapshot.title&&!snapshot.body&&!canvas.querySelector('img')&&!snapshot.cover_url)return null;if(e.saved===revision){try{localStorage.removeItem(prefix()+e.id)}catch{}setStatus('Draft saved privately · '+date(e.stamp));return snapshot;}local();setStatus('Saving private draft…');try{const row={id:e.id,content:snapshot,archived:false};let saved;if(e.cloudExists)saved=await query(client.from('portfolio_post_drafts').update(row).eq('id',e.id).eq('updated_at',e.stamp).select().single());else saved=await query(client.from('portfolio_post_drafts').insert(row).select().single());e.cloudExists=true;e.stamp=saved.updated_at;e.saved=revision;drafts=drafts.filter(d=>d.id!==e.id).concat(saved);if(e.revision===revision){e.dirty=false;try{localStorage.removeItem(prefix()+e.id)}catch{}setStatus('Draft saved privately · '+date(saved.updated_at))}return snapshot}catch(err){e.dirty=true;setStatus('Cloud save failed. '+(e.localFailed?'Keep this tab open.':'Your device copy is safe.')+' '+(err.code==='PGRST116'?'This draft changed in another tab. Reopen it before continuing.':'Retry Save draft when connected.'),true);throw err}});return e.queue}
    e.flush=save;e.backup=local;e.get=get;e.needsUnloadWarning=()=>e.dirty&&e.localFailed;
    function selection(){const s=window.getSelection();if(s?.rangeCount&&canvas.contains(s.anchorNode)&&canvas.contains(s.focusNode))e.range=s.getRangeAt(0).cloneRange()}
    function restore(){canvas.focus();const s=window.getSelection();if(e.range&&canvas.contains(e.range.commonAncestorContainer)){s.removeAllRanges();s.addRange(e.range)}else{const r=document.createRange();r.selectNodeContents(canvas);r.collapse(false);s.removeAllRanges();s.addRange(r)}}
    function command(cmd,value){restore();document.execCommand(cmd,false,value||null);selection();change()}
    function insertImage(url,alt,width){restore();document.execCommand('insertHTML',false,`<p><img src="${esc(url)}" alt="${esc(alt)}" data-width="${width}"></p><p><br></p>`);selection();change()}
    canvas.addEventListener('input',change);canvas.addEventListener('keyup',selection);canvas.addEventListener('mouseup',selection);canvas.addEventListener('blur',selection);canvas.addEventListener('paste',event=>{event.preventDefault();const html=event.clipboardData.getData('text/html'),plain=event.clipboardData.getData('text/plain');restore();document.execCommand('insertHTML',false,html?BlogContent.sanitize(html):BlogContent.legacy(plain));selection();change()});canvas.addEventListener('drop',event=>event.preventDefault());
    const sizeTitle=()=>{title.style.height='auto';title.style.height=title.scrollHeight+'px'};title.oninput=()=>{sizeTitle();if(!slug.dataset.manual)slug.value=title.value.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,180);change()};if(data.slug)slug.dataset.manual='true';slug.oninput=()=>{slug.dataset.manual='true';change()};root.querySelector('#writer-cover').oninput=change;
    const toolbar=root.querySelector('.writer-toolbar');toolbar.addEventListener('mousedown',event=>{if(event.target.closest('button'))event.preventDefault();selection()});
    let insertKind='link';const modal=root.querySelector('#writer-insert');function insertDialog(kind){selection();insertKind=kind;root.querySelector('#writer-insert-title').textContent=kind==='image'?'Add an image':'Add a link';root.querySelector('#writer-insert-url').value='';root.querySelector('#writer-insert-url').required=kind!=='image';root.querySelector('#writer-alt-wrap').hidden=kind!=='image';root.querySelector('#writer-image-options').hidden=kind!=='image';root.querySelector('#writer-insert-alt').value='';modal.showModal()}
    toolbar.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>{const cmd=b.dataset.command;if(cmd==='image'||cmd==='link')insertDialog(cmd);else command(cmd)});
    root.querySelector('#writer-block').onchange=event=>command('formatBlock',event.target.value);root.querySelector('#writer-size').onchange=event=>command('fontSize',event.target.value);root.querySelector('#writer-color').onchange=event=>command('foreColor',event.target.value);root.querySelector('#writer-highlight').onchange=event=>command('hiliteColor',event.target.value);
    root.querySelector('#writer-insert-cancel').onclick=()=>modal.close();root.querySelector('#writer-insert-form').onsubmit=event=>{event.preventDefault();const url=BlogContent.url(root.querySelector('#writer-insert-url').value);if(!url)return ctx.message('Use an HTTPS URL.',true);const alt=root.querySelector('#writer-insert-alt').value,width=root.querySelector('#writer-image-width').value;modal.close();if(insertKind==='image')insertImage(url,alt,width);else command('createLink',url)};
    async function upload(input,inline){const file=input.files?.[0];if(!file)return;ctx.uploading(1);input.disabled=true;setStatus('Uploading image…');try{const url=await ctx.upload(file,'blogs');if(e.closed)return;if(inline){const alt=root.querySelector('#writer-insert-alt').value||file.name.replace(/\.[^.]+$/,'');const width=root.querySelector('#writer-image-width').value;modal.close();insertImage(url,alt,width)}else{root.querySelector('#writer-cover').value=url;change()}await save()}catch(error){ctx.failure(error);setStatus('Image upload failed. Your text is still saved.',true)}finally{input.value='';input.disabled=false;ctx.uploading(-1)}}
    root.querySelector('#writer-inline-file').onchange=event=>upload(event.target,true);root.querySelector('#writer-cover-upload').onchange=event=>upload(event.target,false);
    root.querySelector('#writer-save').onclick=()=>save().catch(ctx.failure);root.querySelector('#writer-back').onclick=async()=>{if(ctx.pending())return ctx.message('Wait for the image upload to finish.',true);try{await save();e.closed=true;ctx.clearEditor();ctx.navigate('drafts')}catch{ctx.message('Your local draft is retained. Retry Save draft before leaving this editor.',true)}};
    root.querySelector('#writer-preview').onclick=()=>{const reader=root.querySelector('#writer-reader'),preview=reader.hidden;reader.innerHTML=BlogContent.sanitize(canvas.innerHTML);reader.hidden=!preview;canvas.hidden=preview;toolbar.hidden=preview;title.readOnly=preview;root.querySelector('#writer-preview').textContent=preview?'Continue writing':'Read preview'};
    root.querySelector('#writer-publish').onclick=async()=>{if(ctx.pending())return ctx.message('Wait for the image upload to finish.',true);let snapshot=get();if(!snapshot.title||(!snapshot.body&&!canvas.querySelector('img')))return ctx.message('Add a title and some text or an image before publishing.',true);if(!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(snapshot.slug))return ctx.message('Use a URL slug with lowercase letters, numbers, and hyphens.',true);if(snapshot.cover_url&&!safeURL(snapshot.cover_url))return ctx.message('The cover image needs an HTTPS URL or website path.',true);const button=root.querySelector('#writer-publish');e.publishing=true;button.disabled=true;canvas.contentEditable='false';root.querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=true);try{await save();snapshot=get();const item={...snapshot,published:true,archived:false,...(!post?.published?{published_at:new Date().toISOString()}:{})};if(post)post=await query(client.from('portfolio_posts').update(item).eq('id',e.id).eq('updated_at',post.updated_at).select().single());else post=await query(client.from('portfolio_posts').insert(item).select().single());await query(client.from('portfolio_post_drafts').update({archived:true}).eq('id',e.id).eq('updated_at',e.stamp).select().single());e.closed=true;try{localStorage.removeItem(prefix()+e.id)}catch{}clearRemember();ctx.clearEditor();await ctx.reload();ctx.navigate('published');ctx.message('Published. Your story is ready to read.')}catch(error){ctx.failure(error);e.publishing=false;button.disabled=false;canvas.contentEditable='true';root.querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=false)}};
    root.querySelector('#writer-unpublish')?.addEventListener('click',async()=>{try{await save();await query(client.from('portfolio_posts').update({published:false}).eq('id',post.id).eq('updated_at',post.updated_at).select().single());e.closed=true;ctx.clearEditor();await ctx.reload();ctx.navigate('drafts');ctx.message('Post moved to private drafts.')}catch(error){ctx.failure(error)}});
    const resizeTitle=()=>{if(!e.closed&&editor===e)sizeTitle()};window.addEventListener('resize',resizeTitle,{signal:(e.resizeController=new AbortController()).signal});document.fonts?.ready.then(resizeTitle);sizeTitle();count();window.scrollTo({top:0,behavior:'instant'});if(draft?.local){change()}
  }
  async function leave(){if(!editor)return true;if(editor.publishing){ctx.message('Publishing is still in progress. Please wait.',true);return false;}if(ctx.pending()){ctx.message('Wait for the image upload to finish.',true);return false;}try{await editor.flush();editor.closed=true;editor.resizeController?.abort();clearRemember();editor=null;return true}catch{return false}}
  function backup(){editor?.backup?.();return editor?.needsUnloadWarning?.()||false}
  function close(){clearTimeout(editor?.timer);editor?.resizeController?.abort();editor?.backup?.();if(editor)editor.closed=true;editor=null}
  window.addEventListener('pagehide',backup);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&editor){backup();editor.flush().catch(()=>{})}});window.addEventListener('online',()=>editor?.flush().catch(()=>{}));
  return {configure,load,render,open,resume,leave,backup,close};
})();
